// Generated by Claude Agentic SDLC Workflow
(function () {
  "use strict";

  // Re-submit the search/sort form as soon as the sort option changes.
  document.querySelectorAll("select[data-autosubmit]").forEach(function (select) {
    select.addEventListener("change", function () {
      if (select.form) {
        select.form.submit();
      }
    });
  });

  // Keep the session alive while a long post is being written (form pages only).
  var keepaliveUrl = document.body.getAttribute("data-keepalive-url");
  var tokenMeta = document.querySelector('meta[name="csrf-token"]');
  if (keepaliveUrl && tokenMeta) {
    setInterval(function () {
      fetch(keepaliveUrl, {
        method: "POST",
        credentials: "same-origin",
        headers: { "X-CSRF-Token": tokenMeta.content }
      }).catch(function () {});
    }, 5 * 60 * 1000);
  }
})();
